static FreqLevel label_id_to_enum(unsigned char id) {
    switch (id) {
        case 0: return FREQ_LEVEL_LOW;
        case 1: return FREQ_LEVEL_MED;
        case 2: return FREQ_LEVEL_HIGH;
        default: return FREQ_LEVEL_HIGH;
    }
}

FreqLevel predict_phase_level(double CPI, double Compute_Density, double Mem_Boundness, double Stall_Ratio, double Branch_MPKI, double Vector_Intensity) {
    double x[KNN_NUM_FEATURES];
    x[0] = (CPI - knn_mean[0]) / knn_scale[0];
    x[1] = (Compute_Density - knn_mean[1]) / knn_scale[1];
    x[2] = (Mem_Boundness - knn_mean[2]) / knn_scale[2];
    x[3] = (Stall_Ratio - knn_mean[3]) / knn_scale[3];
    x[4] = (Branch_MPKI - knn_mean[4]) / knn_scale[4];
    x[5] = (Vector_Intensity - knn_mean[5]) / knn_scale[5];

    double best_dist[KNN_K];
    unsigned char best_lbl[KNN_K];
    for (int i = 0; i < KNN_K; ++i) { best_dist[i] = DBL_MAX; best_lbl[i] = 2; }

    for (size_t i = 0; i < KNN_NUM_SAMPLES; ++i) {
        double d = 0.0;
        for (int j = 0; j < KNN_NUM_FEATURES; ++j) { d += fabs(x[j] - knn_vectors[i][j]); }
        int worst_idx = 0;
        for (int k = 1; k < KNN_K; ++k) { if (best_dist[k] > best_dist[worst_idx]) worst_idx = k; }
        if (d < best_dist[worst_idx]) {
            best_dist[worst_idx] = d;
            best_lbl[worst_idx] = knn_labels[i];
        }
    }

    double votes[3] = {0.0, 0.0, 0.0};
    for (int k = 0; k < KNN_K; ++k) {
        if (best_dist[k] <= 1e-15) return label_id_to_enum(best_lbl[k]);
        votes[best_lbl[k]] += 1.0 / best_dist[k];
    }
    int best = 2;
    if (votes[0] > votes[best]) best = 0;
    if (votes[1] > votes[best]) best = 1;
    return label_id_to_enum((unsigned char)best);
}
